# Quick sanity check: per-session time estimate and weekly sets per muscle group.

sessions = {
 "A (Mon)": {
   "Goblet squat": (4, 10, 90),      # sets, reps, rest sec
   "Dumbbell bench press": (4, 8, 90),
   "Lat pulldown": (3, 10, 75),
   "Seated cable row": (3, 10, 75),
   "Plank": (3, 30, 45),
 },
 "B (Wed)": {
   "Leg press": (4, 10, 90),
   "Dumbbell lunge": (3, 10, 60),
   "Machine shoulder press": (4, 10, 75),
   "Dumbbell bent-over row": (3, 10, 75),
   "Dead bug": (3, 10, 45),
 },
 "C (Fri)": {
   "Machine chest press": (4, 10, 75),
   "Lat pulldown": (3, 10, 75),
   "Seated cable row": (3, 10, 75),
   "Bodyweight squat": (3, 12, 60),
   "Plank": (3, 30, 45),
 },
}

# time per set ~ 45s of work + rest; warmup 5, ramp-up 3, cardio 15, cooldown 2
for day, ex in sessions.items():
    total_sets = sum(s for s, r, rest in ex.values())
    work_min = sum(s * (45/60 + rest/60) for s, r, rest in ex.values())
    est = 5 + 3 + work_min + 15 + 2
    print(f"{day}: {total_sets} sets, lifting ~{work_min:.0f} min, total ~{est:.0f} min")

# weekly sets by muscle
muscle = {
 "Goblet squat": "Quads", "Bodyweight squat": "Quads",
 "Leg press": "Quads", "Dumbbell lunge": "Quads",
 "Dumbbell bench press": "Chest", "Machine chest press": "Chest",
 "Lat pulldown": "Back-vert", "Seated cable row": "Back-horiz", "Dumbbell bent-over row": "Back-horiz",
 "Machine shoulder press": "Shoulders",
 "Plank": "Core", "Dead bug": "Core",
}
week = {}
for day, ex in sessions.items():
    for name, (s, r, rest) in ex.items():
        week[muscle[name]] = week.get(muscle[name], 0) + s
print("\nWeekly hard sets:")
for m, v in week.items():
    print(f"  {m}: {v}")

